def word_count_ascii(text):
    words = []
    current = []
    for ch in text:
        o = ord(ch)
        if 65 <= o <= 90 or 97 <= o <= 122:
            current.append(ch)
        else:
            if current:
                words.append(''.join(current).lower())
                current = []
    if current:
        words.append(''.join(current).lower())
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    result = [[w, counts[w]] for w in counts]
    result.sort(key=lambda x: x[0])
    return result
